class Solution {
    public ListNode deleteDuplicates(ListNode head) {
        ListNode dummy = new ListNode(0, head);
        ListNode previous = dummy;
        while (previous.next != null) {
            if (previous.next.next != null && previous.next.val == previous.next.next.val) {
                int duplicateValue = previous.next.val;
                while (previous.next != null && previous.next.val == duplicateValue) {
                    previous.next = previous.next.next;
                }
            } else {
                previous = previous.next;
            }
        }
        return dummy.next;
    }
}
